//! 🎥️ Individually authored MP4 retained movie, codec and sample relationships.
use super::*;
use semio_framework_os_kernel::sqlite_snapshot::{ValueError, ValueRefusalKind};

fn invalid(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::InvalidValue,message)}
fn work(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::WorkLimit,message)}
fn ownership(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::OwnershipLimit,message)}
fn allocation(message:impl Into<String>)->ValueError{ValueError::new(ValueRefusalKind::AllocationFailed,message)}

use std::collections::BTreeMap;
use semio_framework_os_kernel::{sqlite_snapshot::{artifact::{Cell,Projection,NativeEncodingBound,reconstruct_text,reconstruct_blob},validate_sqlite_database_schema,SnapshotEncoding,SqliteDatabase,SqliteRow,SqliteSnapshotControl,SqliteSnapshotPhase,SqliteValue},ArtifactSqliteSnapshot};
type Entities<'a>=BTreeMap<i64,&'a SqliteRow>;
type Groups<'a>=BTreeMap<i64,Vec<&'a SqliteRow>>;
fn checkpoint(control:&mut SqliteSnapshotControl<'_>,position:usize,total:usize)->Result<(),ValueError>{if position%256==0{control.checkpoint(SqliteSnapshotPhase::ReconstructSnapshot,position,total)?;}Ok(())}
fn entities<'a>(database:&'a SqliteDatabase,table:&str,columns:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Entities<'a>,ValueError>{let rows=&database.table(table)?.rows;let mut result=BTreeMap::new();for(position,row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;if row.values.len()!=columns||row.rowid<=0||row.integer(0)?!=row.rowid||result.insert(row.rowid,row).is_some(){return Err(invalid(format!("{table} requires positive unique aliased identities and exact columns")));}}Ok(result)}
fn singleton<'a>(rows:&Entities<'a>)->Result<&'a SqliteRow,ValueError>{if rows.len()!=1{return Err(invalid("MP4 requires singleton identity one"));}rows.get(&1).copied().ok_or_else(||invalid("MP4 requires singleton identity one"))}
fn owners(rows:&Entities<'_>,parents:&Entities<'_>,required:bool,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{for(position,id)in rows.keys().enumerate(){checkpoint(control,position,rows.len())?;if !parents.contains_key(id){return Err(invalid("MP4 one-to-one entity has unknown owner"));}}if required&&rows.len()!=parents.len(){return Err(invalid("MP4 required entity is missing"));}Ok(())}
fn groups<'a>(rows:&Entities<'a>,parents:&Entities<'_>,control:&mut SqliteSnapshotControl<'_>)->Result<Groups<'a>,ValueError>{let mut result:Groups<'a>=BTreeMap::new();for(position,&row)in rows.values().enumerate(){checkpoint(control,position,rows.len())?;let parent=row.integer(1)?;if !parents.contains_key(&parent){return Err(invalid("MP4 ordered entity has unknown owner"));}result.entry(parent).or_default().push(row);}for rows in result.values_mut(){checkpoint(control,0,rows.len())?;let mut slots=vec![None;rows.len()];for(position,&row)in rows.iter().enumerate(){checkpoint(control,position,rows.len())?;let ordinal=usize::try_from(row.integer(2)?).map_err(|error|invalid(error.to_string()))?;if slots.get_mut(ordinal).ok_or_else(||invalid("MP4 ordinals must be dense"))?.replace(row).is_some(){return Err(invalid("MP4 ordinals must be unique"));}}rows.clear();for(position,row)in slots.into_iter().enumerate(){checkpoint(control,position,0)?;rows.push(row.ok_or_else(||invalid("MP4 ordinals must be dense"))?);}}Ok(result)}
fn number<T:TryFrom<i64>>(row:&SqliteRow,column:usize)->Result<T,ValueError>{T::try_from(row.integer(column)?).map_err(|_|invalid("MP4 integer exceeds native width"))}
fn u64_value(row:&SqliteRow,column:usize)->Result<u64,ValueError>{let text=row.text(column)?;if text.len()>20{return Err(invalid("MP4 unsigned decimal exceeds native width"));}let value=text.parse::<u64>().map_err(|error|invalid(error.to_string()))?;if value.to_string()!=text{return Err(invalid("MP4 unsigned decimal must be canonical"));}Ok(value)}
fn boolean(row:&SqliteRow,column:usize)->Result<bool,ValueError>{match row.integer(column)?{0=>Ok(false),1=>Ok(true),_=>Err(invalid("MP4 requires boolean integer"))}}
fn text(row:&SqliteRow,column:usize,control:&mut SqliteSnapshotControl<'_>)->Result<String,ValueError>{reconstruct_text(control,row.text(column)?)}
fn optional_text(row:&SqliteRow,column:usize,control:&mut SqliteSnapshotControl<'_>)->Result<Option<String>,ValueError>{if matches!(row.values.get(column),Some(SqliteValue::Null)){Ok(None)}else{Ok(Some(text(row,column,control)?))}}
fn optional_cell(value:&Option<String>)->Cell<'_>{value.as_deref().map_or(Cell::Null,Cell::Text)}
fn ordinal(value:usize)->Result<Cell<'static>,ValueError>{Ok(Cell::Integer(i64::try_from(value).map_err(|error|work(error.to_string()))?))}
fn write_matrix(out:&mut Projection<'_,'_>,table:&str,parent:i64,values:&[i32;9])->Result<(),ValueError>{for(index,value)in values.iter().enumerate(){out.insert(table,&[Cell::Integer(parent),ordinal(index)?,Cell::Integer(i64::from(*value))])?;}Ok(())}
fn read_matrix(rows:Option<&Vec<&SqliteRow>>,control:&mut SqliteSnapshotControl<'_>)->Result<[i32;9],ValueError>{let rows=rows.ok_or_else(||invalid("MP4 matrix is missing"))?;if rows.len()!=9{return Err(invalid("MP4 matrix requires nine components"));}let mut result=[0;9];for(index,row)in rows.iter().enumerate(){checkpoint(control,index,9)?;result[index]=number(row,3)?;}Ok(result)}
fn write_nals(out:&mut Projection<'_,'_>,table:&str,parent:i64,values:&[Vec<u8>])->Result<(),ValueError>{for(index,value)in values.iter().enumerate(){out.insert(table,&[Cell::Integer(parent),ordinal(index)?,Cell::Blob(value)])?;}Ok(())}
fn read_nals(rows:Option<&Vec<&SqliteRow>>,control:&mut SqliteSnapshotControl<'_>)->Result<Vec<Vec<u8>>,ValueError>{let mut result=Vec::new();for row in rows.into_iter().flatten(){checkpoint(control,result.len(),0)?;result.push(reconstruct_blob(control,row.blob(3)?)?);}Ok(result)}
fn encoding_text(bound:&mut NativeEncodingBound<'_,'_>,value:&str)->Result<(),ValueError>{bound.add(128)?;bound.repeated(value.len(),24)}
fn encoding_nals(bound:&mut NativeEncodingBound<'_,'_>,values:&[Vec<u8>])->Result<(),ValueError>{bound.add(128)?;for value in values{bound.add(128)?;bound.repeated(value.len(),std::mem::size_of::<semio_framework_dsl_record::FieldValue>()*2+32)?;}Ok(())}
fn native_value_bytes(snapshot:&Mp4Snapshot)->Result<usize,ValueError>{
 fn add(total:usize,count:usize)->Result<usize,ValueError>{total.checked_add(count).ok_or_else(||ownership("MP4 native value byte count overflow"))}
 fn repeated(count:usize,size:usize)->Result<usize,ValueError>{count.checked_mul(size).ok_or_else(||ownership("MP4 native repeated byte count overflow"))}
 fn nals(mut total:usize,values:&[Vec<u8>])->Result<usize,ValueError>{for value in values{total=add(total,value.len())?;}Ok(total)}
 let mut total=add(add(snapshot.schema.len(),snapshot.ftyp.major_brand.len())?,4)?;for brand in &snapshot.ftyp.compatible_brands{total=add(total,brand.len())?;}total=add(total,74)?;for value in [&snapshot.movie.title,&snapshot.movie.encoder].into_iter().flatten(){total=add(total,value.len())?;}
 for track in &snapshot.tracks{total=add(total,18)?;total=nals(nals(total,&track.codec.sps)?,&track.codec.pps)?;if let Some(extension)=&track.codec.extension{total=add(total,3)?;total=nals(total,&extension.sps_ext)?;}if let Some(hevc)=&track.codec.hevc{total=add(total,28)?;for array in &hevc.arrays{total=add(total,2)?;total=nals(total,&array.nal_units)?;}}let metadata=&track.metadata;total=add(add(add(total,96)?,metadata.language.len())?,metadata.handler_name.len())?;total=add(total,repeated(metadata.edits.len(),20)?)?;total=add(add(total,32)?,metadata.visual.compressor_name.len())?;if let Some(color)=&metadata.color{total=add(add(total,6)?,color.color_type.len())?;if color.full_range.is_some(){total=add(total,1)?;}}if metadata.pixel_aspect_ratio.is_some(){total=add(total,8)?;}if metadata.bitrate.is_some(){total=add(total,12)?;}total=add(total,repeated(track.chunk_sample_counts.len(),4)?)?;for sample in &track.samples{total=add(add(total,9)?,sample.data.len())?;}}
 Ok(total)
}
impl ArtifactSqliteSnapshot for Mp4Snapshot{
 fn decode_sqlite_snapshot_native(payload:&store::io::IoPayload,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{let snapshot=store::decode_sqlite_snapshot_record_native(payload,<Self as store::ArtifactDsl>::envelope_id(),Self::__dsl_spec_producer(),|record,native|Self::__dsl_from_record_controlled(record,native),control)?;control.check_value_bytes(native_value_bytes(&snapshot)?)?;Ok(snapshot)}
