 fn encode_sqlite_snapshot_native(&self,encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<store::io_schema::IoPayload,ValueError>{
  control.check_value_bytes(native_value_bytes(self)?)?;control.checkpoint(SqliteSnapshotPhase::EncodeNative,0,0)?;let add=|count:usize,size:usize|count.checked_add(size).ok_or_else(||work("Native semantic row count overflow"));let mut rows=add(add(12,self.ftyp.compatible_brands.len())?,self.tracks.len().checked_mul(13).ok_or_else(||work("MP4 track row count overflow"))?)?;control.check_rows(rows)?;for(index,track)in self.tracks.iter().enumerate(){rows=add(add(rows,track.codec.sps.len())?,track.codec.pps.len())?;if let Some(extension)=&track.codec.extension{rows=add(add(rows,1)?,extension.sps_ext.len())?}if let Some(hevc)=&track.codec.hevc{rows=add(add(rows,1)?,hevc.arrays.len())?;control.check_rows(rows)?;for(index,array)in hevc.arrays.iter().enumerate(){rows=add(rows,array.nal_units.len())?;control.check_rows(rows)?;if(index+1)%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,index+1,hevc.arrays.len())?}}}let metadata=&track.metadata;for size in[metadata.edits.len(),usize::from(metadata.color.is_some()),usize::from(metadata.pixel_aspect_ratio.is_some()),usize::from(metadata.bitrate.is_some()),track.chunk_sample_counts.len(),track.samples.len()]{rows=add(rows,size)?}control.check_rows(rows)?;if(index+1)%256==0{control.checkpoint(SqliteSnapshotPhase::EncodeNative,index+1,self.tracks.len())?}}
