 }

 fn preflight_sqlite_snapshot_encoding(&self,_encoding:SnapshotEncoding,control:&mut SqliteSnapshotControl<'_>)->Result<(),ValueError>{let mut bound=NativeEncodingBound::new(control)?;bound.add(32768)?;encoding_text(&mut bound,&self.schema)?;encoding_text(&mut bound,&self.ftyp.major_brand)?;for brand in &self.ftyp.compatible_brands{encoding_text(&mut bound,brand)?;}if let Some(value)=&self.movie.title{encoding_text(&mut bound,value)?;}if let Some(value)=&self.movie.encoder{encoding_text(&mut bound,value)?;}for track in &self.tracks{bound.add(16384)?;let codec=&track.codec;encoding_nals(&mut bound,&codec.sps)?;encoding_nals(&mut bound,&codec.pps)?;if let Some(extension)=&codec.extension{bound.add(1024)?;encoding_nals(&mut bound,&extension.sps_ext)?;}if let Some(hevc)=&codec.hevc{bound.add(4096)?;for array in &hevc.arrays{bound.add(512)?;encoding_nals(&mut bound,&array.nal_units)?;}}let metadata=&track.metadata;encoding_text(&mut bound,&metadata.language)?;encoding_text(&mut bound,&metadata.handler_name)?;encoding_text(&mut bound,&metadata.visual.compressor_name)?;bound.repeated(metadata.edits.len(),1024)?;if let Some(color)=&metadata.color{bound.add(1024)?;encoding_text(&mut bound,&color.color_type)?;}if metadata.pixel_aspect_ratio.is_some(){bound.add(512)?;}if metadata.bitrate.is_some(){bound.add(512)?;}bound.repeated(track.chunk_sample_counts.len(),std::mem::size_of::<semio_framework_dsl_record::FieldValue>()*2+64)?;for sample in &track.samples{bound.add(1024)?;bound.repeated(sample.data.len(),16)?;}}bound.finish()}
 fn to_sqlite_database(&self,control:&mut SqliteSnapshotControl<'_>)->Result<SqliteDatabase,ValueError>{let mut out=Projection::new(Self::SQLITE_SCHEMA,control)?;out.insert("mp4_document",&[Cell::Text(&self.schema)])?;out.insert_key("mp4_ftyp",1,&[Cell::Text(&self.ftyp.major_brand),Cell::Integer(i64::from(self.ftyp.minor_version))])?;for(index,brand)in self.ftyp.compatible_brands.iter().enumerate(){out.insert("mp4_compatible_brand",&[Cell::Integer(1),ordinal(index)?,Cell::Text(brand)])?;}let m=&self.movie;
  out.insert_key("mp4_movie",1,&[Cell::Text(&m.creation_time.to_string()),Cell::Text(&m.modification_time.to_string()),Cell::Integer(i64::from(m.timescale)),Cell::Text(&m.duration.to_string()),Cell::Integer(i64::from(m.rate)),Cell::Integer(i64::from(m.volume)),Cell::Integer(i64::from(m.next_track_id)),optional_cell(&m.title),optional_cell(&m.encoder)])?;write_matrix(&mut out,"mp4_movie_matrix",1,&m.matrix)?;
  for(index,t)in self.tracks.iter().enumerate(){let id=out.insert("mp4_track",&[Cell::Integer(1),ordinal(index)?,Cell::Integer(i64::from(t.track_id)),Cell::Integer(i64::from(t.timescale)),Cell::Integer(i64::from(t.width)),Cell::Integer(i64::from(t.height))])?;let c=&t.codec;out.insert_key("mp4_codec",id,&[Cell::Text(c.format.fourcc()),Cell::Integer(i64::from(c.nal_length_size))])?;write_nals(&mut out,"mp4_avc_sps",id,&c.sps)?;write_nals(&mut out,"mp4_avc_pps",id,&c.pps)?;
   if let Some(e)=&c.extension{out.insert_key("mp4_avc_extension",id,&[Cell::Integer(i64::from(e.chroma_format)),Cell::Integer(i64::from(e.bit_depth_luma_minus8)),Cell::Integer(i64::from(e.bit_depth_chroma_minus8))])?;write_nals(&mut out,"mp4_avc_sps_extension",id,&e.sps_ext)?;}
   if let Some(h)=&c.hevc{out.insert_key("mp4_hevc_config",id,&[Cell::Integer(i64::from(h.general_profile_space)),Cell::Integer(i64::from(h.general_tier_flag)),Cell::Integer(i64::from(h.general_profile_idc)),Cell::Integer(i64::from(h.general_profile_compatibility_flags)),Cell::Text(&h.general_constraint_indicator_flags.to_string()),Cell::Integer(i64::from(h.general_level_idc)),Cell::Integer(i64::from(h.min_spatial_segmentation_idc)),Cell::Integer(i64::from(h.parallelism_type)),Cell::Integer(i64::from(h.chroma_format_idc)),Cell::Integer(i64::from(h.bit_depth_luma_minus8)),Cell::Integer(i64::from(h.bit_depth_chroma_minus8)),Cell::Integer(i64::from(h.avg_frame_rate)),Cell::Integer(i64::from(h.constant_frame_rate)),Cell::Integer(i64::from(h.num_temporal_layers)),Cell::Integer(i64::from(h.temporal_id_nested))])?;for(index,a)in h.arrays.iter().enumerate(){let array=out.insert("mp4_hevc_array",&[Cell::Integer(id),ordinal(index)?,Cell::Integer(i64::from(a.array_completeness)),Cell::Integer(i64::from(a.nal_unit_type))])?;write_nals(&mut out,"mp4_hevc_nal",array,&a.nal_units)?;}}
   let m=&t.metadata;out.insert_key("mp4_track_metadata",id,&[Cell::Text(&m.creation_time.to_string()),Cell::Text(&m.modification_time.to_string()),Cell::Integer(i64::from(m.flags)),Cell::Text(&m.duration.to_string()),Cell::Integer(i64::from(m.layer)),Cell::Integer(i64::from(m.alternate_group)),Cell::Integer(i64::from(m.volume)),Cell::Text(&m.media_duration.to_string()),Cell::Text(&m.media_creation_time.to_string()),Cell::Text(&m.media_modification_time.to_string()),Cell::Text(&m.language),Cell::Integer(i64::from(m.quality)),Cell::Text(&m.handler_name)])?;write_matrix(&mut out,"mp4_track_matrix",id,&m.matrix)?;
   for(index,e)in m.edits.iter().enumerate(){out.insert("mp4_edit",&[Cell::Integer(id),ordinal(index)?,Cell::Text(&e.segment_duration.to_string()),Cell::Integer(e.media_time),Cell::Integer(i64::from(e.media_rate_integer)),Cell::Integer(i64::from(e.media_rate_fraction))])?;}let v=&m.visual;out.insert_key("mp4_visual_sample_entry",id,&[Cell::Integer(i64::from(v.data_reference_index)),Cell::Integer(i64::from(v.version)),Cell::Integer(i64::from(v.revision_level)),Cell::Integer(i64::from(v.vendor)),Cell::Integer(i64::from(v.temporal_quality)),Cell::Integer(i64::from(v.spatial_quality)),Cell::Integer(i64::from(v.horizontal_resolution)),Cell::Integer(i64::from(v.vertical_resolution)),Cell::Integer(i64::from(v.frame_count)),Cell::Text(&v.compressor_name),Cell::Integer(i64::from(v.depth)),Cell::Integer(i64::from(v.color_table_id))])?;
   if let Some(c)=&m.color{out.insert_key("mp4_color",id,&[Cell::Text(&c.color_type),Cell::Integer(i64::from(c.primaries)),Cell::Integer(i64::from(c.transfer)),Cell::Integer(i64::from(c.matrix)),c.full_range.map_or(Cell::Null,|value|Cell::Integer(i64::from(value)))])?;}if let Some(p)=&m.pixel_aspect_ratio{out.insert_key("mp4_pixel_aspect_ratio",id,&[Cell::Integer(i64::from(p.horizontal_spacing)),Cell::Integer(i64::from(p.vertical_spacing))])?;}if let Some(b)=&m.bitrate{out.insert_key("mp4_bitrate",id,&[Cell::Integer(i64::from(b.buffer_size)),Cell::Integer(i64::from(b.maximum)),Cell::Integer(i64::from(b.average))])?;}for(index,count)in t.chunk_sample_counts.iter().enumerate(){out.insert("mp4_chunk_sample_count",&[Cell::Integer(id),ordinal(index)?,Cell::Integer(i64::from(*count))])?;}for(index,s)in t.samples.iter().enumerate(){out.insert("mp4_sample",&[Cell::Integer(id),ordinal(index)?,Cell::Blob(&s.data),Cell::Integer(i64::from(s.duration)),Cell::Integer(i64::from(s.cts_offset)),Cell::Integer(i64::from(s.sync))])?;}
