 fn from_sqlite_database(database:&SqliteDatabase,control:&mut SqliteSnapshotControl<'_>)->Result<Self,ValueError>{validate_sqlite_database_schema(database,Self::SQLITE_SCHEMA,control.limits())?;control.check_database(database,SqliteSnapshotPhase::ReconstructSnapshot)?;
  let documents=entities(database,"mp4_document",2,control)?;let d=singleton(&documents)?;let ftyp=entities(database,"mp4_ftyp",3,control)?;let f=singleton(&ftyp)?;let brands=groups(&entities(database,"mp4_compatible_brand",4,control)?,&ftyp,control)?;let movies=entities(database,"mp4_movie",10,control)?;let m=singleton(&movies)?;let movie_matrix=groups(&entities(database,"mp4_movie_matrix",4,control)?,&movies,control)?;let tracks=entities(database,"mp4_track",7,control)?;let track_rows=groups(&tracks,&documents,control)?;let codecs=entities(database,"mp4_codec",3,control)?;owners(&codecs,&tracks,true,control)?;let sps=groups(&entities(database,"mp4_avc_sps",4,control)?,&codecs,control)?;let pps=groups(&entities(database,"mp4_avc_pps",4,control)?,&codecs,control)?;let extensions=entities(database,"mp4_avc_extension",4,control)?;owners(&extensions,&codecs,false,control)?;let extension_sps=groups(&entities(database,"mp4_avc_sps_extension",4,control)?,&extensions,control)?;let hevc=entities(database,"mp4_hevc_config",16,control)?;owners(&hevc,&codecs,false,control)?;let arrays=entities(database,"mp4_hevc_array",5,control)?;let array_rows=groups(&arrays,&hevc,control)?;let nals=groups(&entities(database,"mp4_hevc_nal",4,control)?,&arrays,control)?;
